var byCode = {};
for (var i = 0; i < list.length; ++i)
    byCode[list[i].code] = list[i];

function info(code)
{
    return byCode[code];
}

var languages = ["pl", "en", "de", "es", "it", "fr"];

function nameOf(c, lang)
{
    return c[lang] !== undefined ? c[lang] : c.en;
}

// strip accents so that "zloty" finds "Złoty" and "ceska" finds "česká"
var plainMap = { "ą":"a","ć":"c","ę":"e","ł":"l","ń":"n","ó":"o","ś":"s","ź":"z","ż":"z",
                 "á":"a","à":"a","â":"a","ä":"a","ã":"a","é":"e","è":"e","ê":"e","ë":"e",
                 "í":"i","î":"i","ï":"i","ô":"o","ö":"o","õ":"o","ú":"u","ü":"u","û":"u",
                 "č":"c","š":"s","ž":"z","ř":"r","ý":"y","ñ":"n","ç":"c","ğ":"g","ı":"i","ş":"s",
                 "ß":"ss","å":"a","ø":"o","œ":"oe","ì":"i","ò":"o","ù":"u" };
function plain(s)
{
    s = String(s).toLowerCase();
    var out = "";
    for (var i = 0; i < s.length; ++i) {
        var ch = s.charAt(i);
        out += plainMap[ch] !== undefined ? plainMap[ch] : ch;
    }
    return out;
}

function matches(c, query)
{
    if (query == "")
        return true;
    var q = plain(query);
    if (c.sym != "" && c.sym.toLowerCase() == query.toLowerCase())
        return true;
    if (plain(c.code).indexOf(q) >= 0)
        return true;
    for (var i = 0; i < languages.length; ++i)
        if (plain(nameOf(c, languages[i])).indexOf(q) >= 0)
            return true;
    return false;
}

function sortedFor(lang)
{
    var copy = list.slice(0);
    copy.sort(function(a, b) {
        var na = plain(nameOf(a, lang)), nb = plain(nameOf(b, lang));
        return na < nb ? -1 : (na > nb ? 1 : 0);
    });
    return copy;
}

function letterOf(c, lang)
{
    // accent-free, so that the scroller and the sort order agree (É -> E)
    return plain(nameOf(c, lang)).charAt(0).toUpperCase();
}

function decimalMark(lang)
{
    return lang == "en" ? "." : ",";
}

function groupDigits(intPart, sep)
{
    var out = "";
    while (intPart.length > 3) {
        out = sep + intPart.substr(intPart.length - 3) + out;
        intPart = intPart.substr(0, intPart.length - 3);
    }
    return intPart + out;
}

function format(value, lang)
{
    if (value === null || value === undefined || isNaN(value))
        return "–";
    var a = Math.abs(value);
    var s;
    if (a == 0)
        s = "0";
    else if (a >= 1)
        s = value.toFixed(2);
    else
        s = value.toPrecision(4);   // small amounts, e.g. 0.0001234 BTC
    if (s.indexOf("e") >= 0)
        s = value.toFixed(10).replace(/0+$/, "");
    var parts = s.split(".");
    var dec = decimalMark(lang);
    var sep = lang == "en" ? "," : (lang == "pl" || lang == "fr" ? " " : ".");
    var neg = parts[0].charAt(0) == "-";
    var ip = neg ? parts[0].substr(1) : parts[0];
    return (neg ? "-" : "") + groupDigits(ip, sep) + (parts.length > 1 ? dec + parts[1] : "");
}

function parseAmount(text)
{
    var v = parseFloat(String(text).replace(/\s/g, "").replace(",", "."));
    return isNaN(v) ? 0 : v;
}


// number for the amount field: no grouping, local decimal mark
function plainNumber(value, lang)
{
    var s = String(Math.round(value * 100) / 100);
    return s.replace(".", decimalMark(lang));
}
